content.content:
1	/**
2	 * What a lesson *serves* — and the schema the in-house decks are written to.
3	 *
4	 * The content-source seam: `LessonContent` is a two-arm discriminated union so
5	 * a lesson can serve either a licensed `.webm` or an in-house deck, one lesson
6	 * at a time, with the compiler refusing any dispatch that forgets an arm.
7	 *
8	 * The deck schema's one non-structural demand is **retrieval**: a deck is
9	 * invalid unless the learner is asked to attempt something before the answer
10	 * is shown. A guideline would be honoured by the first deck and forgotten by
11	 * the twelfth; a schema rule is checked on every deck for free.
12	 */
13	
14	import {
15		type LessonSequenceEntry,
16		lessonEntryById,
17		parseLessonId,
18	} from "./lessonSequence";
19	import { type Lesson, lessons, specialRules, toneRules } from "./symbols";
20	
21	// ============================================================================
22	// The content union
23	// ============================================================================
24	
25	export type LessonContent =
26		| { readonly kind: "video"; readonly url: string }
27		| { readonly kind: "deck"; readonly deckPath: string };
28	
29	/**
30	 * Exhaustive dispatch over `LessonContent`. The `never` default is the point:
31	 * adding a third arm without handling it here is a compile error, which is how
32	 * every downstream dispatch is kept honest too.
33	 */
34	export function describeLessonContent(content: LessonContent): string {
35		switch (content.kind) {
36			case "video":
37				return `video ${content.url}`;
38			case "deck":
39				return `deck ${content.deckPath}`;
40			default: {
41				const _never: never = content;
42				return _never;
43			}
44		}
45	}
46	
47	// ============================================================================
48	// Asset paths
49	// ============================================================================
50	
51	/** Public root under which every generated lesson asset lives. */
52	export const LESSON_ASSET_ROOT = "/lessons";
53	
54	export type DeckPathResult =
55		| { readonly ok: true; readonly path: string }
56		| { readonly ok: false; readonly error: string };
57	
58	/**
59	 * The one place a filesystem/URL path is derived from a lesson id, and so the
60	 * one place the charset has to hold. Task 1.3 owns the containment check at
61	 * the generator's write boundary; this owns the charset.
62	 */
63	export function deckPathForLesson(
64		value: unknown,
65		key = "lessonId",
66	): DeckPathResult {
67		const parsed = parseLessonId(value, key);
68		if (!parsed.ok) return parsed;
69		return { ok: true, path: `${LESSON_ASSET_ROOT}/${parsed.id}/deck.json` };
70	}
71	
72	// ============================================================================
73	// Resolution — three states, and "unresolvable" never reads as "undeclared"
74	// ============================================================================
75	
76	/**
77	 * Lessons whose content is an in-house deck. Empty at the end of task 1.1a:
78	 * every lesson still serves its video. Task 1.4 adds `lesson-01`, and each
79	 * later content task adds its own — that addition is the whole strangler.
80	 */
81	export const DECK_LESSON_IDS: ReadonlySet<string> = new Set<string>();
82	
83	export type LessonContentResolution =
84		/** Declared, and its content source is known. */
85		| { readonly status: "resolved"; readonly content: LessonContent }
86		/** Declared, but no content source can be produced — with the reason. */
87		| { readonly status: "unresolvable"; readonly reason: string }
88		/** No lesson with this id is declared at all. */
89		| { readonly status: "undeclared" };
90	
91	/**
92	 * The three statuses are distinct values on purpose: a lesson whose video is
93	 * missing must never be indistinguishable from a lesson that does not exist,
94	 * because the first is a broken build and the second is an ordinary 404.
95	 */
96	export const LESSON_CONTENT_STATUSES = [
97		"resolved",
98		"unresolvable",
99		"undeclared",
100	] as const;
101	
102	/**
103	 * Content for a lesson that is known to be declared, so the only two outcomes
104	 * left are "resolved" and "unresolvable". Split out from `resolveLessonContent`
105	 * because the undeclared case is decided by the lookup and this one is not —
106	 * a lesson whose video went missing must never read as a lesson that does not
107	 * exist.
108	 */
109	export function lessonContentFor(
110		entry: LessonSequenceEntry,
111		lesson: Lesson | undefined,
112	): LessonContentResolution {
113		if (DECK_LESSON_IDS.has(entry.id)) {
114			const path = deckPathForLesson(entry.id);
115			if (!path.ok) return { status: "unresolvable", reason: path.error };
116			return {
117				status: "resolved",
118				content: { kind: "deck", deckPath: path.path },
119			};
120		}
121		if (!lesson) {
122			return {
123				status: "unresolvable",
124				reason:
125					"lessonId: declared in the sequence but absent from the lessons table",
126			};
127		}
128		if (!lesson.videoUrl) {
129			return {
130				status: "unresolvable",
131				reason: "lessonId: declares neither a deck nor a video url",
132			};
133		}
134		return {
135			status: "resolved",
136			content: { kind: "video", url: lesson.videoUrl },
137		};
138	}
139	
140	export function resolveLessonContent(value: unknown): LessonContentResolution {
141		const lookup = lessonEntryById(value);
142		if (!lookup.ok) return { status: "undeclared" };
143		const entry = lookup.entry;
144		return lessonContentFor(
145			entry,
146			lessons.find((lesson) => lesson.number === entry.legacyNumber),
147		);
148	}
149	
150	// ============================================================================
151	// The rules block
152	// ============================================================================
153	
154	/**
155	 * A rule a lesson teaches, resolved from the tables that already declare it
156	 * (`toneRules`, `specialRules`) via the ids the lessons table already lists.
157	 * Rule slides render from this — they carry no prose of their own, so the
158	 * slide and the rule cannot drift apart.
159	 */
160	export interface LessonRule {
161		readonly id: string;
162		readonly kind: "tone" | "special";
163		readonly title: string;
164		readonly text: string;
165	}
166	
167	export function lessonRules(legacyNumber: number): readonly LessonRule[] {
168		const lesson = lessons.find((candidate) => candidate.number === legacyNumber);
169		if (!lesson) return [];
170	
171		const tone = lesson.toneRulesIntroduced.flatMap<LessonRule>((id) => {
172			const rule = toneRules.find((candidate) => candidate.id === id);
173			if (!rule) return [];
174			return [
175				{
176					id: rule.id,
177					kind: "tone",
178					title: `${rule.consonantClass} class + ${rule.syllableType} syllable = ${rule.resultingTone} tone`,
179					text: rule.description,
180				},
181			];
182		});
183		const special = lesson.specialRulesIntroduced.flatMap<LessonRule>((id) => {
184			const rule = specialRules.find((candidate) => candidate.id === id);
185			if (!rule) return [];
186			return [
187				{
188					id: rule.id,
189					kind: "special",
190					title: rule.title,
191					text: rule.description,
192				},
193			];
194		});
195		return [...tone, ...special];
196	}
197	
198	// ============================================================================
199	// The deck schema
200	// ============================================================================
201	
202	export interface DeckExpositionSlide {
203		readonly kind: "exposition";
204		readonly id: string;
205		readonly heading: string;
206		readonly body: readonly string[];
207	}
208	
209	/**
210	 * A prompt the learner attempts. It names the reveal that answers it and
211	 * carries no answer itself — the attempt is the mechanism, so an answer
212	 * sitting on the same slide defeats the slide entirely.
213	 */
214	export interface DeckRetrievalSlide {
215		readonly kind: "retrieval";
216		readonly id: string;
217		readonly prompt: string;
218		readonly revealSlideId: string;
219	}
220	
221	export interface DeckRevealSlide {
222		readonly kind: "reveal";
223		readonly id: string;
224		readonly retrievalSlideId: string;
225		readonly answers: readonly string[];
226	}
227	
228	/** Renders from the lesson's rules block; holds no prose of its own. */
229	export interface DeckRuleSlide {
230		readonly kind: "rule";
231		readonly id: string;
232		readonly ruleId: string;
233	}
234	
235	export type DeckSlide =
236		| DeckExpositionSlide
237		| DeckRetrievalSlide
238		| DeckRevealSlide
239		| DeckRuleSlide;
240	
241	export interface LessonDeck {
242		readonly lessonId: string;
243		readonly title: string;
244		readonly slides: readonly DeckSlide[];
245	}
246	
247	export type DeckErrorCode =
248		| "malformed"
249		| "lesson-id-refused"
250		| "duplicate-slide-id"
251		| "retrieval-answer-on-same-slide"
252		| "dangling-reveal"
253		| "reveal-before-retrieval"
254		| "missing-retrieval"
255		| "unknown-rule"
256		| "rule-slide-carries-prose";
257	
258	export interface DeckValidationError {
259		readonly code: DeckErrorCode;
260		readonly message: string;
261		readonly slideId?: string;
262	}
263	
264	export type DeckValidationResult =
265		| { readonly ok: true; readonly deck: LessonDeck }
266		| { readonly ok: false; readonly errors: readonly DeckValidationError[] };
267	
268	/** Keys that would put an answer on the retrieval slide itself. */
269	const ANSWER_KEYS = ["answer", "answers", "reveal", "solution"] as const;
270	/** Keys that would let a rule slide state a rule differently from the block. */
271	const PROSE_KEYS = ["heading", "body", "text", "description"] as const;
272	
273	function isRecord(value: unknown): value is Record<string, unknown> {
274		return typeof value === "object" && value !== null && !Array.isArray(value);
275	}
276	
277	function isStringArray(value: unknown): value is string[] {
278		return (
279			Array.isArray(value) && value.every((item) => typeof item === "string")
280		);
281	}
282	
283	function parseSlide(
284		raw: unknown,
285		index: number,
286		errors: DeckValidationError[],
287	): DeckSlide | undefined {
288		const at = `slides[${index}]`;
289		if (!isRecord(raw)) {
290			errors.push({ code: "malformed", message: `${at}: not an object` });
291			return undefined;
292		}
293		const id = raw.id;
294		if (typeof id !== "string" || id.length === 0) {
295			errors.push({ code: "malformed", message: `${at}: missing a string id` });
296			return undefined;
297		}
298	
299		switch (raw.kind) {
300			case "exposition": {
301				if (typeof raw.heading !== "string" || !isStringArray(raw.body)) {
302					errors.push({
303						code: "malformed",
304						slideId: id,
305						message: `${at}: an exposition slide needs a heading and a body of strings`,
306					});
307					return undefined;
308				}
309				return { kind: "exposition", id, heading: raw.heading, body: raw.body };
310			}
311			case "retrieval": {
312				if (
313					typeof raw.prompt !== "string" ||
314					typeof raw.revealSlideId !== "string"
315				) {
316					errors.push({
317						code: "malformed",
318						slideId: id,
319						message: `${at}: a retrieval slide needs a prompt and a revealSlideId`,
320					});
321					return undefined;
322				}
323				const leaked = ANSWER_KEYS.find((key) => key in raw);
324				if (leaked) {
325					errors.push({
326						code: "retrieval-answer-on-same-slide",
327						slideId: id,
328						message: `${at}: retrieval slide carries "${leaked}"; the answer must live on the reveal slide it names, not beside the prompt`,
329					});
330					return undefined;
331				}
332				return {
333					kind: "retrieval",
334					id,
335					prompt: raw.prompt,
336					revealSlideId: raw.revealSlideId,
337				};
338			}
339			case "reveal": {
340				if (
341					typeof raw.retrievalSlideId !== "string" ||
342					!isStringArray(raw.answers)
343				) {
344					errors.push({
345						code: "malformed",
346						slideId: id,
347						message: `${at}: a reveal slide needs a retrievalSlideId and answers`,
348					});
349					return undefined;
350				}
351				return {
352					kind: "reveal",
353					id,
354					retrievalSlideId: raw.retrievalSlideId,
355					answers: raw.answers,
356				};
357			}
358			case "rule": {
359				if (typeof raw.ruleId !== "string") {
360					errors.push({
361						code: "malformed",
362						slideId: id,
363						message: `${at}: a rule slide needs a ruleId`,
364					});
365					return undefined;
366				}
367				const prose = PROSE_KEYS.find((key) => key in raw);
368				if (prose) {
369					errors.push({
370						code: "rule-slide-carries-prose",
371						slideId: id,
372						message: `${at}: rule slide carries "${prose}"; a rule slide renders from the lesson's rules block so the two cannot disagree`,
373					});
374					return undefined;
375				}
376				return { kind: "rule", id, ruleId: raw.ruleId };
377			}
378			default:
379				errors.push({
380					code: "malformed",
381					slideId: id,
382					message: `${at}: unknown slide kind`,
383				});
384				return undefined;
385		}
386	}
387	
388	function checkRetrieval(
389		slides: readonly DeckSlide[],
390		errors: DeckValidationError[],
391	): void {
392		const retrievalsSeen = new Set<string>();
393		let pairs = 0;
394	
395		for (const slide of slides) {
396			if (slide.kind === "retrieval") {
397				retrievalsSeen.add(slide.id);
398				continue;
399			}
400			if (slide.kind !== "reveal") continue;
401	
402			const target = slides.find(
403				(candidate) =>
404					candidate.kind === "retrieval" &&
405					candidate.id === slide.retrievalSlideId,
406			);
407			if (!target) {
408				errors.push({
409					code: "dangling-reveal",
410					slideId: slide.id,
411					message: `reveal "${slide.id}" names no retrieval slide that exists`,
412				});
413				continue;
414			}
415			if (!retrievalsSeen.has(slide.retrievalSlideId)) {
416				errors.push({
417					code: "reveal-before-retrieval",
418					slideId: slide.id,
419					message: `reveal "${slide.id}" comes before the retrieval step it answers; the learner must attempt first`,
420				});
421				continue;
422			}
423			pairs += 1;
424		}
425	
426		if (pairs === 0) {
427			errors.push({
428				code: "missing-retrieval",
429				message:
430					"deck has no retrieval step before a reveal: a deck must ask the learner to attempt at least one answer before showing it",
431			});
432		}
433	}
434	
435	export function validateDeck(value: unknown): DeckValidationResult {
436		const errors: DeckValidationError[] = [];
437	
438		if (!isRecord(value)) {
439			return {
440				ok: false,
441				errors: [{ code: "malformed", message: "deck: not an object" }],
442			};
443		}
444		const lessonId = parseLessonId(value.lessonId, "lessonId");
445		if (!lessonId.ok) {
446			return {
447				ok: false,
448				errors: [{ code: "lesson-id-refused", message: lessonId.error }],
449			};
450		}
451		if (typeof value.title !== "string" || value.title.length === 0) {
452			errors.push({ code: "malformed", message: "deck: missing a title" });
453		}
454		if (!Array.isArray(value.slides)) {
455			return {
456				ok: false,
457				errors: [
458					...errors,
459					{ code: "malformed", message: "deck: slides must be an array" },
460				],
461			};
462		}
463	
464		const slides: DeckSlide[] = [];
465		const seenIds = new Set<string>();
466		value.slides.forEach((raw, index) => {
467			const slide = parseSlide(raw, index, errors);
468			if (!slide) return;
469			if (seenIds.has(slide.id)) {
470				errors.push({
471					code: "duplicate-slide-id",
472					slideId: slide.id,
473					message: `slides[${index}]: slide id is already used`,
474				});
475				return;
476			}
477			seenIds.add(slide.id);
478			slides.push(slide);
479		});
480	
481		checkRetrieval(slides, errors);
482	
483		const entry = lessonEntryById(lessonId.id);
484		const rules = entry.ok ? lessonRules(entry.entry.legacyNumber) : [];
485		for (const slide of slides) {
486			if (slide.kind !== "rule") continue;
487			if (!rules.some((rule) => rule.id === slide.ruleId)) {
488				errors.push({
489					code: "unknown-rule",
490					slideId: slide.id,
491					message: `rule slide "${slide.id}" names a rule this lesson does not declare`,
492				});
493			}
494		}
495	
496		if (errors.length > 0) return { ok: false, errors };
497		return {
498			ok: true,
499			deck: { lessonId: lessonId.id, title: value.title as string, slides },
500		};
501	}
502	
503	/**
504	 * The rendering source for a rule slide: the lesson's own rules-block entry.
505	 * There is no other text on the slide, which is what makes "the lesson applies
506	 * the rule as it states it" checkable at all.
507	 */
508	export function renderRuleSlide(
509		deck: LessonDeck,
510		slide: DeckRuleSlide,
511	): LessonRule | undefined {
512		const entry = lessonEntryById(deck.lessonId);
513		if (!entry.ok) return undefined;
514		return lessonRules(entry.entry.legacyNumber).find(
515			(rule) => rule.id === slide.ruleId,
516		);
517	}
