import type { CardRepository } from "../../ports/CardRepository";
import type { LearnerStateRepository } from "../../ports/LearnerStateRepository";
import type { ApprenticeService } from "../../shared/services/ApprenticeService";
import { reconcileGeneratedCards } from "../../shared/services/reconcileCards";
import type { PropertyCard } from "../../shared/types";
import { SrsSchedule } from "../../srs/value-objects/SrsSchedule";
import {
	getSymbolsByLesson,
	lessons,
	rareVowels,
	ThaiConsonant,
	ThaiToneMark,
	ThaiVowel,
	thaiNumerals,
	toneMarkRules,
	toneRules,
} from "../data/symbols";
import { ScriptPropertyCard } from "../entities/ScriptPropertyCard";
import { generateCardsForLesson } from "./ScriptCardGenerator";

const TOTAL_LESSONS = 25;

export interface LessonInfo {
	lessonNumber: number;
	title: string;
	focus: string;
	cards: PropertyCard[];
}

export interface ConsonantSummary {
	character: string;
	name: string;
	nameRomanized: string;
	nameMeaning: string;
	classType: string;
	initialSound: string;
	finalSound: string;
	hasDeadEnding: boolean;
	isAspirated: boolean;
	mnemonic?: string;
	audioUrl?: string;
}

export interface VowelSummary {
	character: string;
	name: string;
	sound: string;
	length: string;
	position: string;
	mnemonic?: string;
	audioUrl?: string;
}

export interface ToneMarkSummary {
	character: string;
	name: string;
	midClassTone: string;
	highClassTone: string | null;
	lowClassTone: string | null;
	audioUrl?: string;
}

export interface RareVowelSummary {
	character: string;
	name: string;
	pronunciation: string;
	length: string;
	notes: string;
}

export interface NumeralSummary {
	character: string;
	arabic: number;
	word: string;
	romanization: string;
}

export interface ToneRuleSummary {
	id: string;
	description: string;
}

export interface LessonSummary {
	lessonNumber: number;
	title: string;
	focus: string;
	videoUrl?: string;
	consonants: ConsonantSummary[];
	vowels: VowelSummary[];
	toneMarks: ToneMarkSummary[];
	rareVowels: RareVowelSummary[];
	numerals: NumeralSummary[];
	toneRules: ToneRuleSummary[];
}

function toEntity(dto: PropertyCard): ScriptPropertyCard {
	return new ScriptPropertyCard(
		dto.id,
		dto.question,
		dto.correctAnswer,
		dto.choices,
		SrsSchedule.fromDTO(dto.srs),
		dto.symbolCharacter,
		dto.property,
		dto.lessonNumber,
		dto.audioUrl,
		dto.consonantClass,
	);
}

export class LearningService {
	constructor(
		private readonly cardRepo: CardRepository,
		private readonly stateRepo: LearnerStateRepository,
		private readonly apprenticeService?: ApprenticeService,
	) {}

	startLesson(lessonNumber: number): LessonInfo | null {
		if (
			this.apprenticeService &&
			!this.apprenticeService.canStartLesson("script")
		) {
			return null;
		}

		const completedLessons = this.stateRepo.getCompletedLessons();

		if (completedLessons.includes(lessonNumber)) {
			throw new Error(`Lesson ${lessonNumber} is already completed`);
		}

		for (let i = 1; i < lessonNumber; i++) {
			if (!completedLessons.includes(i)) {
				throw new Error(
					`Must complete lesson ${i} before starting lesson ${lessonNumber}`,
				);
			}
		}

		const lessonMeta = lessons.find((l) => l.number === lessonNumber);
		if (!lessonMeta) throw new Error(`Lesson ${lessonNumber} not found`);

		const cards = generateCardsForLesson(lessonNumber);
		const entities = cards.map(toEntity);

		this.cardRepo.saveAll(entities);
		this.stateRepo.setCurrentLesson(lessonNumber);

		return {
			lessonNumber,
			title: lessonMeta.title,
			focus: lessonMeta.focus,
			cards,
		};
	}

	completeLesson(lessonNumber: number): void {
		this.stateRepo.addCompletedLesson(lessonNumber);

		if (this.stateRepo.getCurrentLesson() === lessonNumber) {
			this.stateRepo.setCurrentLesson(null);
		}
	}

	unlearnLesson(lessonNumber: number): void {
		this.stateRepo.removeCompletedLesson(lessonNumber);

		const allCards = this.cardRepo.findAll("script") as ScriptPropertyCard[];
		for (const card of allCards) {
			if (card.lessonNumber === lessonNumber) {
				this.cardRepo.remove(card.id, "script");
			}
		}

		if (this.stateRepo.getCurrentLesson() === lessonNumber) {
			this.stateRepo.setCurrentLesson(null);
		}
	}

	getNextLesson(): number | null {
		const completedLessons = this.stateRepo.getCompletedLessons();
		for (let i = 1; i <= TOTAL_LESSONS; i++) {
			if (!completedLessons.includes(i)) return i;
		}
		return null;
	}

	getLessonSummary(lessonNumber: number): LessonSummary {
		const lessonMeta = lessons.find((l) => l.number === lessonNumber);
		if (!lessonMeta) throw new Error(`Lesson ${lessonNumber} not found`);

		const symbols = getSymbolsByLesson(lessonNumber);

		return {
			lessonNumber,
			title: lessonMeta.title,
			focus: lessonMeta.focus,
			videoUrl: lessonMeta.videoUrl,
			consonants: symbols
				.filter((s): s is ThaiConsonant => s instanceof ThaiConsonant)
				.map((c) => ({
					character: c.character,
					name: c.name,
					nameRomanized: c.nameRomanized,
					nameMeaning: c.nameMeaning,
					classType: c.classType,
					initialSound: c.initialSound,
					finalSound: c.finalSound,
					hasDeadEnding: c.hasDeadEnding,
					isAspirated: c.isAspirated,
					mnemonic: c.mnemonic,
					audioUrl: c.audioUrl,
				})),
			vowels: symbols
				.filter((s): s is ThaiVowel => s instanceof ThaiVowel)
				.map((v) => ({
					character: v.character,
					name: v.name,
					sound: v.sound,
					length: v.length,
					position: v.position,
					mnemonic: v.mnemonic,
					audioUrl: v.audioUrl,
				})),
			toneMarks: symbols
				.filter((s): s is ThaiToneMark => s instanceof ThaiToneMark)
				.map((t) => ({
					character: t.character,
					name: t.name,
					midClassTone: t.midClassTone,

/**
 * The declared lesson sequence: the one place lesson identity and lesson
 * ordering are written down.
 *
 * Today a lesson is identified by an integer that is simultaneously its
 * position, its persisted join key (five stores key on it) and its filename.
 * That conflation is what makes resequencing hazardous. This module splits it
 * apart *additively*: a stable `id` per lesson, ordering carried by array
 * order, and `legacyNumber` still holding the integer every persisted store
 * uses today. Nothing persisted changes here — task 1.1b converts the stores.
 *
 * Ordering is read from `lessonSequence` and from nowhere else. In particular
 * the lesson *count* is derived from it (`lessonCount`), never written as a
 * literal: the five `25`s scattered through the app are what a resequence
 * breaks, and they are converted to read this.
 */

/**
 * Lesson ids double as a path segment under `public/lessons/` and as a lookup
 * key, so the charset is closed rather than merely conventional.
 */
export const LESSON_ID_PATTERN = /^[a-z0-9-]{1,64}$/;

export interface LessonSequenceEntry {
	/** Stable identity. Survives resequencing; never reused for another lesson. */
	readonly id: string;
	/** 1-based place in the course. Derived from declaration order. */
	readonly position: number;
	/**
	 * The integer the five persisted stores key on today (CONTEXT.md Rule 1).
	 * Still authoritative until task 1.1b migrates them onto `id`.
	 */
	readonly legacyNumber: number;
}

/** Declaration order is the course order. Positions are assigned from it. */
const DECLARED: readonly Omit<LessonSequenceEntry, "position">[] = [
	{ id: "lesson-01", legacyNumber: 1 },
	{ id: "lesson-02", legacyNumber: 2 },
	{ id: "lesson-03", legacyNumber: 3 },
	{ id: "lesson-04", legacyNumber: 4 },
	{ id: "lesson-05", legacyNumber: 5 },
	{ id: "lesson-06", legacyNumber: 6 },
	{ id: "lesson-07", legacyNumber: 7 },
	{ id: "lesson-08", legacyNumber: 8 },
	{ id: "lesson-09", legacyNumber: 9 },
	{ id: "lesson-10", legacyNumber: 10 },
	{ id: "lesson-11", legacyNumber: 11 },
	{ id: "lesson-12", legacyNumber: 12 },
	{ id: "lesson-13", legacyNumber: 13 },
	{ id: "lesson-14", legacyNumber: 14 },
	{ id: "lesson-15", legacyNumber: 15 },
	{ id: "lesson-16", legacyNumber: 16 },
	{ id: "lesson-17", legacyNumber: 17 },
	{ id: "lesson-18", legacyNumber: 18 },
	{ id: "lesson-19", legacyNumber: 19 },
	{ id: "lesson-20", legacyNumber: 20 },
	{ id: "lesson-21", legacyNumber: 21 },
	{ id: "lesson-22", legacyNumber: 22 },
	{ id: "lesson-23", legacyNumber: 23 },
	{ id: "lesson-24", legacyNumber: 24 },
	{ id: "lesson-25", legacyNumber: 25 },
];

export const lessonSequence: readonly LessonSequenceEntry[] = Object.freeze(
	DECLARED.map((entry, index) =>
		Object.freeze({ ...entry, position: index + 1 }),
	),
);

/**
 * The number of lessons in the course, derived. Consumers that currently hold
 * a literal (`ScriptLessonService.TOTAL_LESSONS`, `AchievementService`,
 * `ProgressPage`, `AchievementBadge`, `LessonPath`) read this instead.
 */
export const lessonCount = lessonSequence.length;

export type LessonIdRefusal = { readonly ok: false; readonly error: string };

export type LessonIdResult =
	| { readonly ok: true; readonly id: string }
	| LessonIdRefusal;

/**
 * The gate every path derivation and every lookup passes an id through.
 *
 * The refusal names `key` and deliberately does **not** echo the value: a
 * rejected id is by definition attacker-shaped (`../../etc/passwd`), and the
 * message ends up in logs and findings.
 */
export function parseLessonId(
	value: unknown,
	key = "lessonId",
): LessonIdResult {
	if (typeof value !== "string") {
		return { ok: false, error: `${key}: expected a string lesson id` };
	}
	if (!LESSON_ID_PATTERN.test(value)) {
		return {
			ok: false,
			error: `${key}: not a lesson id (must match ${LESSON_ID_PATTERN.source})`,
		};
	}
	return { ok: true, id: value };
}

export type LessonLookupResult =
	| { readonly ok: true; readonly entry: LessonSequenceEntry }
	| LessonIdRefusal;

/** Lookup by stable id. Refuses a malformed id rather than simply missing it. */
export function lessonEntryById(
	value: unknown,
	key = "lessonId",
): LessonLookupResult {
	const parsed = parseLessonId(value, key);
	if (!parsed.ok) return parsed;
	const entry = lessonSequence.find((candidate) => candidate.id === parsed.id);
	if (!entry) {
		return { ok: false, error: `${key}: no lesson is declared with this id` };
	}
	return { ok: true, entry };
}

/** Lookup by the integer the persisted stores still use. */
export function lessonEntryByNumber(
	legacyNumber: number,
): LessonSequenceEntry | undefined {
	return lessonSequence.find((entry) => entry.legacyNumber === legacyNumber);
}

