413	 */
414	export function makeGraduatedVocabCard(thai: string): VocabCard {
415		const entry = (vocabularyData as VocabEntry[]).find(
416			(word) => word.thai === thai,
417		);
418		if (!entry) {
419			throw new Error(`no vocabulary entry for "${thai}"`);
420		}
421		return VocabCard.fromDTO({
422			id: `vocab:${thai}:thaiToEnglish`,
423			question: `What does ${thai} mean?`,
424			correctAnswer: "answer",
425			choices: ["answer", "other"],
426			srs: { ...DEFAULT_SRS, learningStep: null },
427			promptWord: thai,
428			property: "thaiToEnglish",
429		});
430	}
431	
432	/**
433	 * One grammar card for `grammarId` — what marks that grammar point
434	 * *learned* for `GrammarService.getUnlockedGrammarPoints()`'s
435	 * learned-prefix rule, letting the next point unlock once its own
436	 * prerequisites are met. The content fields are inert: nothing in the game
437	 * feature reads a grammar card beyond its `grammarId`'s existence.
438	 */
439	export function makeGrammarCard(grammarId: string): GrammarReviewCard {
440		return GrammarReviewCard.fromDTO({
441			id: `grammar:${grammarId}:recognition`,
442			question: `question for ${grammarId}`,
443			correctAnswer: "answer",
444			choices: ["answer", "other"],
445			srs: { ...DEFAULT_SRS },
446			grammarId,
447			property: "recognition",
448		});
449	}
450	
451	// --- Grammar-unlock fixtures, derived from the real data ---
452	
453	const GRAMMAR_BY_LESSON: readonly GrammarEntry[] = [
454		...(grammarData as unknown as GrammarEntry[]),
455	].sort((a, b) => a.lessonNumber - b.lessonNumber);
456	
457	const firstGrammarEntry = GRAMMAR_BY_LESSON[0];
458	if (!firstGrammarEntry) {
459		throw new Error("grammar.json is empty — the unlock fixtures need data");
460	}
461	
462	/** The id `makeGrammarCard` needs to mark the first grammar point learned. */
463	export const FIRST_GRAMMAR_POINT_ID: string = firstGrammarEntry.id;
464	
465	/**
466	 * The fewest graduated vocab words that satisfy every prerequisite of
467	 * `entries`: per word class, the largest `minVocabByClass` requirement
468	 * across the entries, taken from the front of `vocabulary.json`'s words of
469	 * that class, plus every `applicationTemplate` function word (which
470	 * `GrammarService.meetsPrerequisites` also requires graduated). Derived
471	 * from the real data rather than hardcoded so a data change moves the
472	 * fixture instead of silently unlocking nothing. `minTotalVocab` is not
473	 * handled — no early entry sets it — and the throw below surfaces the
474	 * moment one does, rather than guessing whether the class minimums happen
475	 * to cover it.
476	 */
477	function vocabSatisfyingPrerequisitesOf(
478		entries: readonly GrammarEntry[],
479	): readonly string[] {
480		const minByClass = new Map<string, number>();
481		for (const entry of entries) {
482			for (const [wordClass, min] of Object.entries(
483				entry.prerequisites.minVocabByClass,
484			)) {
485				minByClass.set(wordClass, Math.max(minByClass.get(wordClass) ?? 0, min));
486			}
487			const required = entry.prerequisites.minTotalVocab ?? 0;
488			if (required > 0) {
489				throw new Error(
490					`grammar entry "${entry.id}" sets minTotalVocab, which this fixture does not derive — extend vocabSatisfyingPrerequisitesOf`,
491				);
492			}
493		}
494	
495		const words: string[] = [];
496		for (const [wordClass, min] of minByClass) {
497			const ofClass = (vocabularyData as VocabEntry[])
498				.filter((word) => word.word_class === wordClass)
499				.slice(0, min);
500			if (ofClass.length < min) {
501				throw new Error(
502					`vocabulary.json has only ${ofClass.length} "${wordClass}" words, ${min} required`,
503				);
504			}
505			words.push(...ofClass.map((word) => word.thai));
506		}
507		for (const entry of entries) {
508			for (const functionWord of entry.applicationTemplate?.functionWords ?? []) {
509				if (!words.includes(functionWord.thai)) {
510					words.push(functionWord.thai);
511				}
512			}
513		}
514		return words;
515	}
516	
517	/**
518	 * Graduating exactly these words (see `makeGraduatedVocabCard` /
519	 * `graduatedVocab`) unlocks the first grammar point — and, with no grammar
520	 * card learned, *only* the first: `getUnlockedGrammarPoints()`'s
521	 * learned-prefix rule keeps every later prerequisite-satisfying point
522	 * locked behind an unlearned earlier one.
523	 */
524	export const UNLOCKS_FIRST_GRAMMAR_POINT: readonly string[] =
525		vocabSatisfyingPrerequisitesOf(GRAMMAR_BY_LESSON.slice(0, 1));
526	
527	/**
528	 * Graduating these words *and* marking the first point learned
529	 * (`learnedGrammar: [FIRST_GRAMMAR_POINT_ID]`) unlocks exactly the first
530	 * two grammar points: the second's prerequisites are met and the only
531	 * earlier point is learned, while everything after stays locked behind the
532	 * unlearned second point.
533	 */
534	export const UNLOCKS_FIRST_TWO_GRAMMAR_POINTS: readonly string[] =
535		vocabSatisfyingPrerequisitesOf(GRAMMAR_BY_LESSON.slice(0, 2));
536	
537	/** A `GameItem` with a pre-assigned direction, for fixed-round tests. */
538	export function makeSymbolItem(
539		symbolCharacter: string,
540		challengeDirection: SymbolChallengeDirection,
541		overrides: Partial<Omit<SymbolItemContent, "kind">> = {},
542	): GameItem {
543		return {
544			kind: "symbol",
545			symbolCharacter,
546			promptText: symbolCharacter,
547			correctAnswer: `${symbolCharacter} name`,
548			audioUrl: `/audio/${symbolCharacter}.mp3`,
549			...overrides,
550			challengeDirection,
551		};
552	}
553	
554	/** A persisted history entry, for seeding history stores. */
555	export function makeHistoryEntry(
556		overrides: Partial<GameHistoryEntry> = {},
557	): GameHistoryEntry {
558		return {
559			kind: "practice",
560			id: "entry-1",
561			playedAt: "2026-09-01T10:00:00.000Z",
562			pools: ["script"],
563			itemCount: 4,
564			summary: {
565				ratingCounts: { 1: 0, 2: 1, 3: 0, 4: 2, 5: 1 },
566				ratedCount: 4,
567				accuracy: 75,
568			},
569			...overrides,
570		};
571	}
572	
573	/** A `JsonStore` whose every load reports corrupt — the unavailable case. */
574	export class CorruptJsonStore<T> implements JsonStore<T> {
575		load(): JsonStoreLoadResult<T> {
576			return { status: "corrupt" };
577		}
578	
579		save(): JsonStoreSaveResult {
580			return { status: "ok" };
581		}
582	}
583	
584	// --- Game use-case factories ---
585	
586	export interface MakeGameOptions {
587		symbols?: readonly string[];
588		historyStore?: JsonStore<GameHistoryEntry[]>;
589	}
590	
591	/** A real `PlayGameUseCase` over in-memory persistence. */
592	export function makeGame(options: MakeGameOptions = {}): PlayGameUseCase {
593		const cardRepo = new StorageCardRepository(new InMemoryStorage());
594		cardRepo.saveAll((options.symbols ?? []).map(makeScriptCard));
595		return new PlayGameUseCase(
596			new GameItemSelectionService([new SymbolGameItemSource(cardRepo)]),
597			new StorageGameHistoryRepository(
598				options.historyStore ?? new InMemoryJsonStore<GameHistoryEntry[]>(),
599			),
600			// No composition rounds from this factory: it wires one symbol source
601			// and no grammar, so an empty unlocked set is the honest answer.
602			() => [],
603		);
604	}
605	
606	class FixedRoundGame extends PlayGameUseCase {
607		constructor(
608			private readonly fixedItems: readonly GameItem[],
609			selection: GameItemSelectionService,
610			historyRepository: GameHistoryRepository,
611		) {
612			super(selection, historyRepository, () => []);
613		}
614	
615		override startRound(config: GameRoundConfig): GameItem[] {
616			return this.fixedRound(config.itemCount);
617		}
618	
619		/**
620		 * Composition rounds are fixed the same way practice rounds are, so a
621		 * page test can drive either mode from one list of pre-built items.
622		 */
623		override startCompositionRound(count: number): GameItem[] {
624			return this.fixedRound(count);
625		}
626	
627		private fixedRound(count: number): GameItem[] {
628			return this.fixedItems.slice(
629				0,
630				normalizeRequestedCount(count, this.fixedItems.length),
631			);
632		}
633	}
634	
635	/**
636	 * A `PlayGameUseCase` whose rounds are exactly `items`, in order, with the
637	 * directions the test pre-assigned — everything else (rating, finishing,
638	 * history) stays real.
639	 */
640	export function makeFixedRoundGame(
641		items: readonly GameItem[],
642		options: Pick<MakeGameOptions, "historyStore"> = {},
643	): { game: PlayGameUseCase; historyStore: JsonStore<GameHistoryEntry[]> } {
644		const historyStore =
645			options.historyStore ?? new InMemoryJsonStore<GameHistoryEntry[]>();
646		const cardRepo = new StorageCardRepository(new InMemoryStorage());
647		const game = new FixedRoundGame(
648			items,
649			new GameItemSelectionService([new SymbolGameItemSource(cardRepo)]),
650			new StorageGameHistoryRepository(historyStore),
651		);
652		return { game, historyStore };
653	}
654	
655	// --- Conversation practice port stub ---
656	
657	/**
658	 * A `ConversationPracticePort` that answers with whatever the test sets and
659	 * records what it was asked. Defaults to `"unavailable"` on every call — the
660	 * honest default for a harness with no backend behind it.
661	 *
662	 * `next` and `judgement` are queues, not single values: a multi-turn test
663	 * (task 3.3) drives several turns in one render, and each one needs its own
664	 * answer — `nextResults`/`judgements` are shifted one at a time, falling
665	 * back to the last-set single value once exhausted so a single-turn test
666	 * can keep just setting `.judgement`/`.session` without touching the queues.
667	 */
668	export class StubConversationPracticePort implements ConversationPracticePort {
669		session: ConversationSessionStartResult = { status: "unavailable" };
670		judgement: ConversationJudgeResult = { status: "unavailable" };
671		nextResult: ConversationNextResult = { status: "exhausted" };
672		readonly nextResults: ConversationNextResult[] = [];
673		readonly judgements: ConversationJudgeResult[] = [];
674		readonly startSessionCalls: string[][] = [];
675		readonly nextCalls: string[] = [];
676		readonly judgeCalls: {
677			sessionId: string;
678			questionText: string;
679			replyAudio: Blob;
680		}[] = [];
681	
682		async startSession(
683			knownWords: string[],
684		): Promise<ConversationSessionStartResult> {
685			this.startSessionCalls.push(knownWords);
686			return this.session;
687		}
688	
689		async next(sessionId: string): Promise<ConversationNextResult> {
690			this.nextCalls.push(sessionId);
691			return this.nextResults.length > 0
692				? (this.nextResults.shift() as ConversationNextResult)
693				: this.nextResult;
694		}
695	
696		async judgeReply(
697			sessionId: string,
698			questionText: string,
699			replyAudio: Blob,
700		): Promise<ConversationJudgeResult> {
701			this.judgeCalls.push({ sessionId, questionText, replyAudio });
702			return this.judgements.length > 0
703				? (this.judgements.shift() as ConversationJudgeResult)
704				: this.judgement;
705		}
706	}
707	
708	// --- The harness itself ---
709	
710	export interface AppHarness {
711		value: AppContextValue;
712		storage: InMemoryStorage;
713		cardRepo: StorageCardRepository;
714		historyStore: InMemoryJsonStore<GameHistoryEntry[]>;
715		game: PlayGameUseCase;
716	}
717	
718	export interface MakeAppValueOptions {
719		/** Characters (existing in `symbols.ts`) to seed one script card each for. */
720		symbols?: readonly string[];
721		/** Sentence ids (existing in `sentences.json`) to seed one card each for. */
722		sentences?: readonly string[];
723		/**
724		 * Thai words (existing in `vocabulary.json`) to seed one
725		 * `toneIdentification` card each for — what makes a word eligible for
726		 * tone practice.
727		 */
728		toneWords?: readonly string[];
729		/**
730		 * Thai words (existing in `vocabulary.json`) to seed one *graduated*
731		 * vocab card each for — what counts toward grammar prerequisites and so
732		 * toward composition mode's unlocked set. `UNLOCKS_FIRST_GRAMMAR_POINT`
733		 * is the derived set that unlocks exactly the first grammar point.
734		 */
735		graduatedVocab?: readonly string[];
736		/**
737		 * Grammar ids (existing in `grammar.json`) to seed one grammar card
738		 * each for — what marks those points *learned*, letting later points
739		 * unlock once their own prerequisites are met.
740		 */
741		learnedGrammar?: readonly string[];
742		/**
743		 * Pre-built cards to seed as-is, for shapes the named options above don't
744		 * cover (e.g. a `selfValidation` sentence card, built with
745		 * `makeSelfValidationSentenceCard`).
746		 */
747		extraCards?: readonly ReviewableCard[];
748	}
749	
750	/**
751	 * A complete in-memory `AppContextValue`: every use case and service the
752	 * real `AppContext.tsx` wires, built over `InMemoryStorage` instead of
753	 * `localStorage`, plus a real `PlayGameUseCase` over an in-memory history
754	 * store. `refresh` and `checkAchievements` are inert stubs — pass overrides
755	 * if a test needs either to be observable.
756	 */
757	export function makeAppValue(options: MakeAppValueOptions = {}): AppHarness {
758		const storage = new InMemoryStorage();
759		const cardRepo = new StorageCardRepository(storage);
760		const stateRepo = new StorageLearnerStateRepository(storage);
761		const apprenticeService = new ApprenticeService(
762			cardRepo,
763			MAX_APPRENTICE_ITEMS,
764			stateRepo,
765		);
766		const leechService = new LeechService(cardRepo);
767		const learningService = new LearningService(
768			cardRepo,
769			stateRepo,
770			apprenticeService,
771		);
772		const reviewService = new ReviewService(cardRepo, stateRepo, {
773			// Sentence sessions are chosen by coverage of the material rather than
774			// by per-card overdueness — see `SentenceCoverageSelector`.
775			sentence: new SentenceCoverageSelector(
776				sentenceData as unknown as SentenceEntry[],
777			),
778		});
779		const vocabularyService = new VocabularyService(
780			cardRepo,
781			stateRepo,
782			vocabularyData as VocabEntry[],
783			apprenticeService,
784		);
785		const grammarService = new GrammarService(
786			cardRepo,
787			grammarData as unknown as GrammarEntry[],
788			apprenticeService,
789			vocabularyData as VocabEntry[],
790		);
791		const sentenceService = new SentenceService(
792			cardRepo,
793			sentenceData as unknown as SentenceEntry[],
794			vocabularyService,
795			apprenticeService,
796		);
797	
798		cardRepo.saveAll((options.symbols ?? []).map(makeScriptCard));
799		cardRepo.saveAll((options.sentences ?? []).map(makeSentenceCard));
800		cardRepo.saveAll((options.toneWords ?? []).map(makeToneVocabCard));
801		cardRepo.saveAll((options.graduatedVocab ?? []).map(makeGraduatedVocabCard));
802		cardRepo.saveAll((options.learnedGrammar ?? []).map(makeGrammarCard));
803		cardRepo.saveAll([...(options.extraCards ?? [])]);
804	
805		const historyStore = new InMemoryJsonStore<GameHistoryEntry[]>();
806		// Register every source the real `AppContext.tsx` registers — a harness
807		// that registers a subset silently diverges from production per pool
808		// (see task 1.3), which is how "works in the harness, empty in the app"
809		// bugs are born.
810		const game = new PlayGameUseCase(
811			new GameItemSelectionService(
812				[
813					new SymbolGameItemSource(cardRepo),
814					new WordGameItemSource(cardRepo, vocabularyData as VocabEntry[]),
815					new SentenceGameItemSource(
816						cardRepo,
817						sentenceData as unknown as SentenceEntry[],
818					),
819				],
820				cardRepo,
821				new ToneGameItemSource(cardRepo, vocabularyData as VocabEntry[]),
822			),
823			new StorageGameHistoryRepository(historyStore),
824			// The real `GrammarService`, exactly as `AppContext.tsx` wires it — a
825			// harness that stubs this diverges from production on the one
826			// question composition mode asks (see task 1.3's own note above).
827			() => grammarService.getUnlockedGrammarPoints(),
828		);
829	
830		const value: AppContextValue = {
831			state: storage.load(),
832			refresh: () => {},
833			lesson: new StartLessonUseCase(
834				learningService,
835				vocabularyService,
836				grammarService,
837				sentenceService,
838			),
839			review: new ConductReviewUseCase(
840				reviewService,
841				new NotificationScheduler(),
842			),
843			dashboard: new QueryDashboardUseCase(
844				cardRepo,
845				apprenticeService,
846				leechService,
847			),
848			data: new ManageDataUseCase(stateRepo),
849			items: new ManageItemsUseCase(cardRepo),
850			vocab: vocabularyService,
851			conversationPractice: new StubConversationPracticePort(),
852			sentence: sentenceService,
853			checkAchievements: () => [],
854			game,
855		};
856	
857		return { value, storage, cardRepo, historyStore, game };
858	}
859	
860	export interface RenderWithAppOptions extends MakeAppValueOptions {
861		/** Initial router entry, default `/`. */
862		route?: string;
863	}
864	
865	/**
866	 * Renders `ui` inside `<AppContext.Provider>` (a fresh in-memory
867	 * `AppContextValue`, with `overrides` merged in) and a `MemoryRouter`.
868	 * Returns Testing-Library's render result plus the harness internals.
869	 */
870	export function renderWithApp(
871		ui: ReactElement,
872		overrides: Partial<AppContextValue> = {},
873		options: RenderWithAppOptions = {},
874	): RenderResult & { app: AppHarness } {
875		const app = makeAppValue({
876			symbols: options.symbols,
877			sentences: options.sentences,
878			toneWords: options.toneWords,
879			graduatedVocab: options.graduatedVocab,
880			learnedGrammar: options.learnedGrammar,
881			extraCards: options.extraCards,
882		});
883		const value: AppContextValue = { ...app.value, ...overrides };
884		const result = render(
885			<AppContext.Provider value={value}>
886				<MemoryRouter initialEntries={[options.route ?? "/"]}>{ui}</MemoryRouter>
887			</AppContext.Provider>,
888		);
889		return Object.assign(result, { app: { ...app, value, game: value.game } });
890	}
