// --- localStorage fake (jsdom's own is unreliable here, see module docs) ---

export class FakeLocalStorage implements Storage {
	private store = new Map<string, string>();

	get length(): number {
		return this.store.size;
	}

	clear(): void {
		this.store.clear();
	}

	getItem(key: string): string | null {
		return this.store.has(key) ? (this.store.get(key) as string) : null;
	}

	key(index: number): string | null {
		return Array.from(this.store.keys())[index] ?? null;
	}

	removeItem(key: string): void {
		this.store.delete(key);
	}

	setItem(key: string, value: string): void {
		this.store.set(key, value);
	}
}

let fakeLocalStorage = new FakeLocalStorage();

/** The per-test `localStorage` stand-in installed on `globalThis`. */
export function getFakeLocalStorage(): FakeLocalStorage {
	return fakeLocalStorage;
}

// --- Audio stub (jsdom throws synchronously from `play()`) ---

export class StubAudio {
	static createdUrls: string[] = [];
	currentTime = 0;

	constructor(readonly src?: string) {
		StubAudio.createdUrls.push(src ?? "");
	}

	play(): Promise<void> {
		return Promise.resolve();
	}

	pause(): void {}
}

/** URLs passed to `new Audio(url)` since the current test began. */
export function createdAudioUrls(): readonly string[] {
	return StubAudio.createdUrls;
}

// --- Object-URL stub (jsdom implements neither create nor revoke) ---

let objectUrlCount = 0;
let revokedUrls: string[] = [];

/** URLs passed to `URL.revokeObjectURL` since the current test began. */
export function revokedObjectUrls(): readonly string[] {
	return revokedUrls;
}

// --- Microphone stubs (jsdom has neither `MediaRecorder` nor `mediaDevices`) ---

/** The MIME type and bytes every stubbed recording produces. */
export const MIC_FIXTURE_MIME_TYPE = "audio/webm;codecs=opus";
const MIC_FIXTURE_BYTES = Uint8Array.from([0x1a, 0x45, 0xdf, 0xa3]);

export type MicPermission = "granted" | "denied" | "error";

let micPermission: MicPermission = "granted";

/**
 * What the next `getUserMedia` call does: hand back a stream, refuse with a
 * `NotAllowedError` (the permission prompt declined), or fail some other way
 * — the three outcomes `useMicRecorder` maps to `recording`/`denied`/`error`.
 * Resets to `"granted"` before each test.
 */
export function setMicPermission(permission: MicPermission): void {
	micPermission = permission;
}

/**
 * A `MediaRecorder` that records one fixed `Blob`. `stop()` synchronously
 * emits the fixture and fires `onstop`, so a test drives the real
 * `useMicRecorder` state machine without any timing games.
 */
export class StubMediaRecorder {
	state: "inactive" | "recording" = "inactive";
	ondataavailable: ((event: { data: Blob }) => void) | null = null;
	onstop: (() => void) | null = null;

	readonly mimeType = MIC_FIXTURE_MIME_TYPE;

	start(): void {
		this.state = "recording";
	}

	stop(): void {
		this.state = "inactive";
		this.ondataavailable?.({
			data: new Blob([MIC_FIXTURE_BYTES], { type: MIC_FIXTURE_MIME_TYPE }),
		});
		this.onstop?.();
	}
}

// --- fetch stub (jsdom has none; `DeckSlide` loads deck JSON with it) ---

type FetchOutcome =
	| { readonly kind: "json"; readonly body: unknown; readonly status: number }
	| { readonly kind: "error" };

let fetchOutcomes = new Map<string, FetchOutcome>();

/** The next `fetch(url)` in this test resolves with `body` as JSON. */
export function stubDeckJson(url: string, body: unknown, status = 200): void {
	fetchOutcomes.set(url, { kind: "json", body, status });
}

/** The next `fetch(url)` in this test rejects, as a network failure would. */
export function stubDeckFetchError(url: string): void {
	fetchOutcomes.set(url, { kind: "error" });
}

// --- Canvas 2D stub (jsdom has no 2D context without the canvas package) ---

export const canvas2d = {
	clearRect: vi.fn(),
	beginPath: vi.fn(),
	moveTo: vi.fn(),
	lineTo: vi.fn(),
	stroke: vi.fn(),
	lineCap: "round",
	lineJoin: "round",
	lineWidth: 4,
	strokeStyle: "",
};

beforeEach(() => {
	fakeLocalStorage = new FakeLocalStorage();
	globalThis.localStorage = fakeLocalStorage;
	globalThis.Audio = StubAudio as unknown as typeof Audio;
	StubAudio.createdUrls = [];
	objectUrlCount = 0;
	revokedUrls = [];
	URL.createObjectURL = () => {
		objectUrlCount += 1;
		return `blob:test/${objectUrlCount}`;
	};
	URL.revokeObjectURL = (url: string) => {
		revokedUrls.push(url);
	};
	micPermission = "granted";
	globalThis.MediaRecorder =
		StubMediaRecorder as unknown as typeof MediaRecorder;
	Object.defineProperty(globalThis.navigator, "mediaDevices", {
		configurable: true,
		value: {
			getUserMedia: async () => {
				if (micPermission === "denied") {
					throw new DOMException("Permission denied", "NotAllowedError");
				}
				if (micPermission === "error") {
					throw new Error("No recording device");
				}
				return {
					getTracks: () => [{ stop: () => {} }],
				} as unknown as MediaStream;
			},
		},
	});
	canvas2d.clearRect.mockClear();
	canvas2d.beginPath.mockClear();
	canvas2d.moveTo.mockClear();
	canvas2d.lineTo.mockClear();
	canvas2d.stroke.mockClear();
	if (typeof HTMLMediaElement !== "undefined") {
		HTMLMediaElement.prototype.play = () => Promise.resolve();
		HTMLMediaElement.prototype.pause = () => {};
	}
	if (typeof HTMLCanvasElement !== "undefined") {
		HTMLCanvasElement.prototype.getContext = (() =>
			canvas2d) as unknown as HTMLCanvasElement["getContext"];
	}
});

afterEach(() => {
	cleanup();
	Reflect.deleteProperty(globalThis, "localStorage");
});

// --- Fixtures ---

