					throw new Error(`request for ${deckPath} failed (${res.status})`);
				}
				return res.json();
			})
			.then((raw) => {
				if (cancelled) return;
				const result = validateDeck(raw);
				if (!result.ok) {
					setState({
						status: "error",
						message: result.errors.map((e) => e.message).join("; "),
					});
					return;
				}
				setState({
					status: "ready",
					deck: result.deck,
					audioUrls: extractAudioUrls(raw, result.deck.lessonId),
				});
